//! The hooks that follow a merge or a rebase and bring the generated files to
//! the tree it made. Neither can refuse what has already happened, so a failure
//! to regenerate is said plainly and the exit stays 0.

use mockspace_manifest::kept_ours::KEPT_OURS_SHELL;

use super::*;

/// The warning both hooks give when the regeneration itself failed: the tree is
/// committed with generated files that may no longer match it, and this is the fix.
const STALE: &str = "the generated files in this tree may be STALE, the regeneration failed. Run \\`cargo mock\\` and commit what it changes.";

/// The post-merge hook: after a merge that made its own commit, bring the
/// generated files to the merged tree in a follow-up commit.
///
/// A `pre-merge-commit` hook cannot do this, because git does not carry index
/// changes it makes into the merge commit. A merge that stopped on a conflict
/// elsewhere never reaches here and is regenerated at the commit that concludes
/// it, by the pre-commit hook.
///
/// Only a real merge commit is followed up, so a fast-forward pull pays
/// nothing. Never blocks: the merge has already happened.
pub(crate) fn gen_post_merge(user_hook: &Path) -> String {
    let chain = chain_user_hook(user_hook, false);

    format!(
        r##"#!/usr/bin/env bash
{MANAGED_MARKER}
# Generated by mockspace. The repository's own .git/hooks/post-merge runs after it.

# the merge driver asks whether a hook here would regenerate in this working tree
[ -n "${{MOCKSPACE_PROBE:-}}" ] && exit 0

{chain}
{KEPT_OURS_SHELL}
# a merge commit has a second parent; a fast-forward or a squash has none to follow up
if [ "$(git rev-list --parents -n 1 HEAD | wc -w)" -lt 3 ]; then
    ms_chain "$@"
fi

if ! cargo mock --generate-only --commit-regenerated 2>&1; then
    echo "post-merge: {STALE}" >&2
elif ms_kept_live; then
    # exit 0 and the files are still marked: an engine that did not do what was asked
    ms_kept_say
fi
ms_chain "$@"
"##
    )
}

/// The post-rewrite hook: after a rebase, regenerate on the rewritten tip and
/// commit what differs on top of it.
///
/// The driver keeps ours for a generated file while the rebase replays commits,
/// so the commits in between may carry the upstream's copy; the tip is the
/// generation of the final tree. `amend` rewrites one commit and no merge
/// brought a generated file in, so it is left alone.
///
/// The hook is handed the rewritten commits on stdin, which the repository's
/// own hook of the same name is owed. Never blocks.
pub(crate) fn gen_post_rewrite(user_hook: &Path) -> String {
    let path = user_hook.display();

    format!(
        r##"#!/usr/bin/env bash
{MANAGED_MARKER}
# Generated by mockspace. The repository's own .git/hooks/post-rewrite runs after it.

# the merge driver asks whether a hook here would regenerate in this working tree
[ -n "${{MOCKSPACE_PROBE:-}}" ] && exit 0

REWRITE_STDIN=$(cat)
USER_HOOK="{path}"
ms_chain() {{
    [ -x "$USER_HOOK" ] || exit 0
    printf '%s\n' "$REWRITE_STDIN" | "$USER_HOOK" "$@"
    exit $?
}}

{KEPT_OURS_SHELL}
[ "${{1:-}}" = rebase ] || ms_chain "$@"

if ! cargo mock --generate-only --commit-regenerated=rebase 2>&1; then
    echo "post-rewrite: {STALE}" >&2
elif ms_kept_live; then
    ms_kept_say
fi
ms_chain "$@"
"##
    )
}

#[cfg(test)]
mod tests {
    use std::process::Stdio;

    use super::*;

    /// A scratch directory holding the generated hook, a `cargo` that records
    /// how it was called and succeeds or fails as told, and a repository hook
    /// that records the stdin it was given.
    struct Rig {
        dir:  tempfile::TempDir,
        hook: PathBuf,
    }

    fn executable(path: &Path, body: &str) {
        fs::write(path, body).unwrap();
        fs::set_permissions(path, fs::Permissions::from_mode(0o755)).unwrap();
    }

    fn rig(hook_text: impl Fn(&Path) -> String, cargo_exit: i32) -> Rig {
        let dir = tempfile::tempdir().unwrap();
        let p = dir.path();
        executable(
            &p.join("cargo"),
            &format!(
                "#!/bin/sh\necho \"$@\" >> \"{}/cargo.log\"\nexit {cargo_exit}\n",
                p.display()
            ),
        );
        executable(
            &p.join("own"),
            &format!(
                "#!/bin/sh\ncat > \"{0}/own.stdin\"\necho \"$@\" > \"{0}/own.args\"\n",
                p.display()
            ),
        );
        let hook = p.join("hook");
        executable(&hook, &hook_text(&p.join("own")));
        Rig {
            dir,
            hook,
        }
    }

    impl Rig {
        fn run(&self, args: &[&str], stdin: &str) -> (bool, String) {
            use std::io::Write;
            let path = format!(
                "{}:{}",
                self.dir.path().display(),
                std::env::var("PATH").unwrap()
            );
            let mut child = Command::new("bash")
                .arg(&self.hook)
                .args(args)
                .env("PATH", path)
                .current_dir(self.dir.path())
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .unwrap();
            child
                .stdin
                .take()
                .unwrap()
                .write_all(stdin.as_bytes())
                .unwrap();
            let out = child.wait_with_output().unwrap();
            (
                out.status.success(),
                String::from_utf8_lossy(&out.stderr).to_string(),
            )
        }

        fn read(&self, name: &str) -> String {
            fs::read_to_string(self.dir.path().join(name)).unwrap_or_default()
        }
    }

    #[test]
    fn a_rebase_regenerates_and_an_amend_does_not() {
        let r = rig(|own| gen_post_rewrite(own), 0);
        let (ok, _) = r.run(&["amend"], "old new\n");
        assert!(ok);
        assert_eq!(r.read("cargo.log"), "", "an amend regenerates nothing");
        let (ok, _) = r.run(&["rebase"], "old new\n");
        assert!(ok);
        assert_eq!(
            r.read("cargo.log"),
            "mock --generate-only --commit-regenerated=rebase\n"
        );
    }

    #[test]
    fn the_repositorys_own_post_rewrite_is_owed_the_arguments_and_the_stdin() {
        let r = rig(|own| gen_post_rewrite(own), 0);
        for kind in ["amend", "rebase"] {
            r.run(&[kind], "aaa bbb\nccc ddd\n");
            assert_eq!(r.read("own.stdin"), "aaa bbb\nccc ddd\n", "{kind}");
            assert_eq!(r.read("own.args").trim(), kind);
        }
    }

    #[test]
    fn a_failed_regeneration_says_the_files_are_stale_and_what_fixes_it() {
        for (name, text) in [
            (
                "post-rewrite",
                Box::new(|own: &Path| gen_post_rewrite(own)) as Box<dyn Fn(&Path) -> String>,
            ),
            ("post-merge", Box::new(|own: &Path| gen_post_merge(own))),
        ] {
            let r = rig(text, 1);
            // a merge commit has a second parent; give the post-merge hook one
            let git = |args: &[&str]| {
                let out = Command::new("git")
                    .args(args)
                    .current_dir(r.dir.path())
                    .output()
                    .unwrap();
                assert!(out.status.success(), "git {args:?}");
            };
            git(&["init", "-q", "-b", "dev"]);
            git(&[
                "-c",
                "user.name=t",
                "-c",
                "user.email=t@e.c",
                "commit",
                "-q",
                "--allow-empty",
                "-m",
                "base",
            ]);
            git(&["switch", "-q", "-c", "side"]);
            git(&[
                "-c",
                "user.name=t",
                "-c",
                "user.email=t@e.c",
                "commit",
                "-q",
                "--allow-empty",
                "-m",
                "side",
            ]);
            git(&["switch", "-q", "dev"]);
            git(&[
                "-c",
                "user.name=t",
                "-c",
                "user.email=t@e.c",
                "commit",
                "-q",
                "--allow-empty",
                "-m",
                "dev",
            ]);
            git(&[
                "-c",
                "user.name=t",
                "-c",
                "user.email=t@e.c",
                "merge",
                "-q",
                "--no-ff",
                "-m",
                "merge",
                "side",
            ]);
            let arg = if name == "post-rewrite" { "rebase" } else { "0" };
            let (ok, stderr) = r.run(&[arg], "");
            assert!(ok, "{name}: cannot abort what already happened");
            assert!(stderr.contains("STALE"), "{name}: {stderr}");
            assert!(stderr.contains("`cargo mock`"), "{name}: {stderr}");
        }
    }
}
